<script>
const receiptUnits = @json($units->map(fn ($unit) => ['id' => $unit->id, 'name' => $unit->name])->values());
function addReceiptUomFields() { document.querySelectorAll('#receipt-lines tbody tr').forEach(row => { const input = row.querySelector('input[name="received_qty[]"]'); if (!input || input.dataset.uomReady) return; input.dataset.uomReady = '1'; const select = document.createElement('select'); select.name = 'uom_id[]'; select.className = 'form-select form-select-sm mb-1'; select.innerHTML = '<option value="">Stock UOM</option>' + receiptUnits.map(unit => `<option value="${unit.id}">${unit.name}</option>`).join(''); input.parentElement.prepend(select); }); }
